func encode_runs(text: String) -> String {
    var compressed = [Char]()
    var currentChar = Char()
    var count = 1

    for char in text {
        if char == currentChar {
            count += 1
        } else {
            compressed.append(char)
            compressed.append(count)
            currentChar = char
            count = 1
        }
    }

    compressed.append(char)
    compressed.append(count)

    return compressed.map { String($0) }.join("")
}
